async function onMessage(msg: Message) {
  const { eventId, orderId } = JSON.parse(msg.body);
  const claimed = await db.run(
    'INSERT INTO processed_events (event_id) VALUES (?) ON CONFLICT DO NOTHING', [eventId]);
  if (claimed.changes === 0) return msg.ack();
  try {
    await markPaid(orderId);
    msg.ack();
  } catch (err) {
    await db.run('DELETE FROM processed_events WHERE event_id = ?', [eventId]);
    msg.nack({ requeue: true });
  }
}
